package com.ptms.service;import com.ptms.dto.SettingsDto;import com.ptms.exception.BusinessRuleException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalTime;import java.util.*;
@Service @Transactional public class SettingsService{private final JdbcTemplate db;public SettingsService(JdbcTemplate db){this.db=db;}private String get(String k,String d){List<String>x=db.query("select setting_value from app_setting where setting_key=?",(r,n)->r.getString(1),k);return x.isEmpty()?d:x.get(0);}public SettingsDto get(){return new SettingsDto(get("weekdayStart","06:00"),get("weekdayEnd","12:00"),get("weekendStart","06:00"),get("weekendEnd","12:30"),Integer.parseInt(get("bufferMinutes","0")),get("ticketTypes","1,2,4,6,8,12"),Integer.parseInt(get("warning1h","5")),Integer.parseInt(get("warning2h","5")),Integer.parseInt(get("warning4h","5")),Integer.parseInt(get("warning6h","5")),Integer.parseInt(get("warning8h","5")),Integer.parseInt(get("warning12h","5")));}public SettingsDto save(SettingsDto s){validateTime(s.weekdayStart(),s.weekdayEnd());validateTime(s.weekendStart(),s.weekendEnd());Set<Integer> allowed=Set.of(1,2,4,6,8,12);try{for(String x:s.ticketTypes().split(","))if(!allowed.contains(Integer.parseInt(x.trim())))throw new Exception();}catch(Exception e){throw new BusinessRuleException("Ticket types must use 1, 2, 4, 6, 8 or 12 hours");}put("weekdayStart",s.weekdayStart());put("weekdayEnd",s.weekdayEnd());put("weekendStart",s.weekendStart());put("weekendEnd",s.weekendEnd());put("bufferMinutes",String.valueOf(s.bufferMinutes()));put("ticketTypes",s.ticketTypes());put("warning1h",String.valueOf(s.warning1h()));put("warning2h",String.valueOf(s.warning2h()));put("warning4h",String.valueOf(s.warning4h()));put("warning6h",String.valueOf(s.warning6h()));put("warning8h",String.valueOf(s.warning8h()));put("warning12h",String.valueOf(s.warning12h()));return get();}private void validateTime(String a,String b){if(!LocalTime.parse(b).isAfter(LocalTime.parse(a)))throw new BusinessRuleException("Parking pass end time must be after start time");}private void put(String k,String v){db.update("insert into app_setting(setting_key,setting_value) values(?,?) on duplicate key update setting_value=values(setting_value)",k,v);}}
